// Optional native preview. No provider request, asset download, iframe or automatic motion.
export function attachCinematic({host,signal,load=()=>import('./cinematic-world.mjs')}){
 const doc=host.ownerDocument;let world=null,disposed=false,generation=0,pointer=[.5,.5];
 host.innerHTML='<h2>Procedural living world</h2><p>Original Frutiger and Frawgy procedural geometry, shaders and mascots. Separate from room placement; artist-world assets are excluded. Open explicitly; motion starts paused.</p><button type="button" data-cinema-open>Open 3D preview</button><button type="button" data-cinema-close disabled>Close 3D preview</button><label>Scene <select data-cinema-theme><option value="frutiger">Frutiger</option><option value="frawgy">Frawgy</option></select></label><label><input type="checkbox" data-cinema-motion> Animate scene</label><label><input type="checkbox" data-cinema-interaction> Enable preview pointer and keyboard response</label><button type="button" data-cinema-pulse disabled>Pulse preview lighting</button><p>Interactive response is opt-in and requires animation. Within the preview, move the pointer or use arrow keys; Home centers the camera. Space or Enter pulses lighting. Reduced motion and hidden pages suppress response.</p><p role="status" data-cinema-status>Not loaded.</p><div data-cinema-view hidden tabindex="0" role="group" aria-label="Interactive procedural preview. Arrow keys adjust camera; Home centers; Space or Enter pulses lighting."></div>';
 const one=s=>host.querySelector(s),view=one('[data-cinema-view]'),status=one('[data-cinema-status]'),motion=one('[data-cinema-motion]'),open=one('[data-cinema-open]'),close=one('[data-cinema-close]'),interaction=one('[data-cinema-interaction]'),pulseButton=one('[data-cinema-pulse]');
 const media=doc.defaultView?.matchMedia?.('(prefers-reduced-motion: reduce)');
 function active(){return !disposed&&world?.supported&&motion.checked&&interaction.checked&&!media?.matches&&!doc.hidden;}
 function center(){pointer=[.5,.5];world?.setPointer?.(.5,.5);}
 function syncInteraction(){const enabled=Boolean(!disposed&&world?.supported&&motion.checked&&!media?.matches&&!doc.hidden);interaction.disabled=!enabled;pulseButton.disabled=!active();if(!active())center();}
 function move(x,y){if(!active()||!Number.isFinite(x)||!Number.isFinite(y))return;pointer=[Math.max(0,Math.min(1,x)),Math.max(0,Math.min(1,y))];world.setPointer?.(...pointer);}
 function pulse(){if(active())world.pulse?.(.45);}
 function applyMotion(){if(disposed)return;const reduced=Boolean(media?.matches);if(reduced)motion.checked=false;motion.disabled=reduced||!world?.supported;world?.setMotion(Boolean(motion.checked)&&!reduced&&!doc.hidden);if(reduced)interaction.checked=false;syncInteraction();if(world?.supported)status.textContent=reduced?'3D ready; motion paused for reduced-motion preference.':motion.checked&&!doc.hidden?'3D ready; animation running.':'3D ready; animation paused.';}
 function stop(){generation++;center();interaction.checked=false;interaction.disabled=true;pulseButton.disabled=true;world?.dispose();world=null;view.replaceChildren();view.hidden=true;motion.checked=false;motion.disabled=true;close.disabled=true;open.disabled=false;status.textContent='Preview closed; GPU resources released.';}
 open.addEventListener('click',async()=>{if(disposed||open.disabled)return;const token=++generation;open.disabled=true;close.disabled=false;status.textContent='Loading local 3D module…';try{const {CinematicWorld}=await load();if(disposed||token!==generation)return;view.hidden=false;world=new CinematicWorld(view);world.setTheme(one('[data-cinema-theme]').value);world.step(0);view.dataset.supported=String(world.supported);if(!world.supported){world.dispose();world=null;view.replaceChildren();view.hidden=true;status.textContent='WebGL unavailable. Room authoring is unaffected.';open.disabled=false;close.disabled=true;}else applyMotion();}catch(e){if(disposed||token!==generation)return;stop();status.textContent='3D preview unavailable. Room authoring is unaffected.';}});
 close.addEventListener('click',stop);motion.addEventListener('change',applyMotion);one('[data-cinema-theme]').addEventListener('change',()=>{if(world){world.setTheme(one('[data-cinema-theme]').value);world.step(0);}});
 interaction.addEventListener('change',syncInteraction);pulseButton.addEventListener('click',pulse);
 const onPointer=event=>{if(!active())return;const rect=view.getBoundingClientRect();if(!(rect.width>0&&rect.height>0))return;move((event.clientX-rect.left)/rect.width,(event.clientY-rect.top)/rect.height);};
 const onLeave=()=>center();
 const onKey=event=>{if(!active()||event.target!==view||event.altKey||event.ctrlKey||event.metaKey)return;const delta={ArrowLeft:[-.1,0],ArrowRight:[.1,0],ArrowUp:[0,-.1],ArrowDown:[0,.1]}[event.key];if(delta){event.preventDefault();move(pointer[0]+delta[0],pointer[1]+delta[1]);}else if(event.key==='Home'){event.preventDefault();center();}else if(event.key===' '||event.key==='Enter'){event.preventDefault();if(!event.repeat)pulse();}};
 view.addEventListener('pointermove',onPointer,{passive:true});view.addEventListener('pointerleave',onLeave);view.addEventListener('keydown',onKey);
 media?.addEventListener?.('change',applyMotion);doc.addEventListener('visibilitychange',applyMotion);applyMotion();
 function dispose(){if(disposed)return;disposed=true;stop();view.removeEventListener('pointermove',onPointer);view.removeEventListener('pointerleave',onLeave);view.removeEventListener('keydown',onKey);media?.removeEventListener?.('change',applyMotion);doc.removeEventListener('visibilitychange',applyMotion);signal?.removeEventListener('abort',dispose);host.replaceChildren();}
 signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return {dispose};
}
